impl AsRef<str> for ObjectType {
    fn as_ref(&self) -> &str {
        &self.0
    }
}

impl From<String> for ObjectType {
    fn from(text: String) -> Self {
        Self(text)
    }
}

impl From<ObjectTypeMember> for ObjectType {
    fn from(member: ObjectTypeMember) -> Self {
        Self(member.as_str().to_owned())
    }
}

impl ObjectTypeMember {
    const MEMBERS: &crate::Members<Self> = &[
        (Self::Button, "Button", None),
        (Self::Checkbox, "Checkbox", None),
        (Self::Dialog, "Dialog", None),
        (Self::Drop, "Drop", None),
        (Self::Edit, "Edit", None),
        (Self::GBox, "GBox", None),
        (Self::Label, "Label", None),
        (Self::LineA, "LineA", None),
        (Self::List, "List", None),
        (Self::Movie, "Movie", None),
        (Self::Note, "Note", None),
        (Self::Pict, "Pict", None),
        (Self::Radio, "Radio", None),
        (Self::RectA, "RectA", None),
        (Self::Scroll, "Scroll", None),
        (Self::Spin, "Spin", None),
        (Self::Shape, "Shape", None),
        (Self::Group, "Group", None),
        (Self::Rect, "Rect", None),
    ];

    /// The text the member stands for.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        crate::member_text(Self::MEMBERS, self)
    }

    /// The Office version that brought the member, from SDK 3.5.1's data; `None` for
    /// ECMA-376's own.
    #[must_use]
    pub fn introduced(self) -> Option<OfficeVersion> {
        crate::member_version(Self::MEMBERS, self)
    }
}

impl ObjectType {
    /// The value the text spells.
    ///
    /// # Errors
    ///
    /// `ValueError` when the text is no value of `ST_ObjectType`; the text stays stored.
    pub fn value(&self) -> Result<ObjectTypeMember, ValueError> {
        crate::member(ObjectTypeMember::MEMBERS, &self.0, "ST_ObjectType")
    }
}

